-- 电商用户表：id 主键、姓名、年龄、性别
CREATE TABLE users (id INTEGER, name TEXT, age INTEGER, gender TEXT);
INSERT INTO users VALUES (1,'张三',25,'M'),(2,'李四',30,'F'),(3,'王五',22,'M');

-- 1. 查所有列（学习阶段可用，生产环境慎用）
SELECT * FROM users;

-- 2. 只查姓名和年龄，按年龄降序
SELECT name, age FROM users ORDER BY age DESC;

-- 3. 过滤 + 截断：男性用户取前 1 条
SELECT name FROM users WHERE gender='M' LIMIT 1;

-- 4. 别名 + 表达式：年龄加 1 变成「明年年龄」
SELECT name AS 姓名, age + 1 AS 明年年龄 FROM users;

CREATE TABLE users (id INTEGER, name TEXT, city TEXT);
INSERT INTO users VALUES (1,'张三','上海'),(2,'李四','北京'),(3,'王五','广州');
CREATE TABLE orders (order_id INTEGER, user_id INTEGER, amount REAL);
INSERT INTO orders VALUES (101,1,150.0),(102,1,80.0),(103,2,300.0),(104,4,200.0);

-- 1. INNER JOIN：订单 104 的 user_id=4 在 users 中不存在，整行被丢弃
SELECT o.order_id, u.name, o.amount
FROM orders o INNER JOIN users u ON o.user_id = u.id
ORDER BY o.order_id;

-- 2. LEFT JOIN：users 全部保留，王五没有订单补 NULL；用 COUNT(o.order_id) 正确计数
SELECT u.name, COUNT(o.order_id) AS order_cnt
FROM users u LEFT JOIN orders o ON u.id = o.user_id
GROUP BY u.name;

-- 3. 从未下过单的用户：LEFT JOIN + 右表主键 IS NULL
SELECT u.name FROM users u
LEFT JOIN orders o ON u.id = o.user_id
WHERE o.order_id IS NULL;

