CREATE TABLE users (id INTEGER, name TEXT);
INSERT INTO users VALUES (1,'张三'),(2,'李四'),(3,'王五'),(4,'赵六');
CREATE TABLE orders (order_id INTEGER, user_id INTEGER, amount REAL);
INSERT INTO orders VALUES (101,1,150.0),(102,1,80.0),(103,2,300.0),(104,3,120.0);

-- 1. 标量子查询：每个订单金额 vs 全站平均金额
SELECT order_id, amount,
       (SELECT AVG(amount) FROM orders) AS avg_amount
FROM orders ORDER BY order_id;

-- 2. IN 子查询：下过单的用户（赵六没下过单，不在结果里）
SELECT id, name FROM users
WHERE id IN (SELECT user_id FROM orders) ORDER BY id;

-- 3. UNION 与 UNION ALL：合并两批用户，观察去重差异
SELECT name FROM users WHERE id IN (1,2)
UNION
SELECT name FROM users WHERE id IN (2,3);

SELECT name FROM users WHERE id IN (1,2)
UNION ALL
SELECT name FROM users WHERE id IN (2,3);

