SELECT category, product_name, amount, rn FROM (
  SELECT category, product_name, amount,
         ROW_NUMBER() OVER (PARTITION BY category ORDER BY amount DESC) AS rn
  FROM (
    SELECT p.category, p.product_name, SUM(s.amount) AS amount
    FROM products p JOIN sales s ON p.product_id = s.product_id
    GROUP BY p.category, p.product_name
  )
) WHERE rn <= 3 ORDER BY category, rn;

SELECT order_date, daily_amount, SUM(daily_amount) OVER (ORDER BY order_date) AS cum_amount
FROM (SELECT order_date, SUM(amount) AS daily_amount FROM orders GROUP BY order_date)
ORDER BY order_date;

