CREATE TABLE users (id INTEGER, name TEXT, email TEXT, phone TEXT);
INSERT INTO users VALUES
 (1,'张三','Zhang.San@Example.COM','13800000001'),
 (2,'李四','LI.SI@Example.com',NULL),
 (3,'王五','wangwu@example.com','13900000003');

-- 1. 大小写归一 + NULL 兜底
SELECT id, name, LOWER(email) AS email, COALESCE(phone, '未填写') AS phone
FROM users ORDER BY id;

-- 2. CASE WHEN：按金额分档
SELECT order_id,
       CASE WHEN amount >= 200 THEN '高额'
            WHEN amount >= 100 THEN '中额'
            ELSE '小额' END AS level
FROM orders ORDER BY order_id;

-- 3. NULL 判断
SELECT id, name FROM users WHERE phone IS NULL;

-- 用 SQLite 观察执行计划：未建索引 vs 建索引
CREATE TABLE orders (order_id INTEGER, user_id INTEGER, amount REAL);
INSERT INTO orders VALUES (1,101,150.0),(2,102,300.0),(3,102,120.0),(4,103,80.0),(5,102,200.0);

-- 未建索引：全表扫描
EXPLAIN QUERY PLAN SELECT order_id FROM orders WHERE user_id = 102;
-- 输出包含 SCAN orders（全表扫描）

-- 建索引后再看：走索引扫描
CREATE INDEX idx_user_id ON orders(user_id);
EXPLAIN QUERY PLAN SELECT order_id FROM orders WHERE user_id = 102;
-- 输出包含 SEARCH orders USING INDEX idx_user_id (user_id=?)

-- 关键认知：索引只改变速度，绝不改变结果集
SELECT order_id, user_id, amount FROM orders WHERE user_id = 102 ORDER BY order_id;

